            // QingceLarder (Liyue / RoomFullOfCheese)
            ["QINGCE_LARDER.title"] =
                "The Qingce Larder",
            ["QINGCE_LARDER.pages.INITIAL.description"] =
                "A collapsed terrace wall below Qingce Village opens onto a "
                + "root-cellar the Feiyun Commerce Guild never finished inventorying "
                + "before the harvest season turned it over to the village instead. "
                + "Jars of pickled radish and aged tofu line the shelves, each one "
                + "labeled in a farmer's careful hand. Behind the last rack, "
                + "something has been fermenting far longer than the others, and it "
                + "smells like it knows you're there.",
            ["QINGCE_LARDER.pages.INITIAL.options.GORGE.title"] =
                "Gorge",
            ["QINGCE_LARDER.pages.INITIAL.options.GORGE.description"] =
                "Choose 2 of 8 random Common cards to add to your Deck. The eight "
                + "jars offered are never duplicates.",
            ["QINGCE_LARDER.pages.INITIAL.options.SEARCH.title"] =
                "Search",
            ["QINGCE_LARDER.pages.INITIAL.options.SEARCH.description"] =
                "Lose 14 HP. Obtain The Chosen Cheese (relic): at the end of "
                + "combat, gain 1 Max HP.",
