            ["NORTHLAND_BANKS_DROWNED_VAULT.pages.INITIAL.options.SECOND_CHEST.description"] =
                "Gain 303–363 Gold. Add Greed (curse) to Deck.",
            ["NORTHLAND_BANKS_DROWNED_VAULT.pages.FIRST_CHEST.description"] =
